INSERT INTO `t_course_syllabus` (`id`, `course_id`, `version`, `status`, `author_teacher`, `course_goals`, `locked_by`) VALUES
(1, 1, 'v2026.1', 'LOCKED', '郭军 (教授)', '目标1: 掌握敏捷Scrum与甘特图项目生命周期规划; 目标2: 具备人机协同与质量管控能力', '李主任'),
(2, 4, 'v2026.1', 'PUBLISHED', '姜琳颖 (副教授)', '掌握单处理器计算机硬件微架构设计与软硬件协同思维', '李主任'),
(3, 6, 'v2026.1', 'PUBLISHED', '赵广生 (讲师)', '掌握高阶算法复杂度分析与核心数据结构选型', '李主任'),
(4, 8, 'v2026.1', 'PUBLISHED', '王伟 (副教授)', '掌握现代操作系统并发控制与内核资源抽象', '李主任');
INSERT INTO `t_graduation_indicator` (`id`, `course_id`, `syllabus_id`, `indicator_code`, `requirement_category`, `indicator_description`, `support_weight`, `target_goal`) VALUES
(1, 1, 1, '1-1', '1. 工程知识', '能够将项目生命周期理论与估算算法用于复杂软件开发建模', 'H', '目标1'),
(2, 1, 1, '2-3', '2. 问题分析', '能够识别软件过程瓶颈与工期死锁风险', 'M', '目标1'),
(3, 1, 1, '3-1', '3. 设计/开发解决方案', '能够设计覆盖敏捷迭代与持续交付的完整工程流程', 'H', '目标2'),
(4, 1, 1, '4-2', '4. 研究', '能够基于实验度量数据科学评价软件缺陷收敛趋势', 'M', '目标2'),
(5, 1, 1, '5-2', '5. 使用现代工具', '能够熟练运用甘特图、Jira及AI敏捷协同工具进行全流程把控', 'H', '目标1'),
(6, 1, 1, '6-1', '6. 工程与社会', '合理分析软件发布对行业与社会的合规性影响', 'M', '目标1'),
(7, 1, 1, '7-1', '7. 环境和可持续发展', '评价软件工程生命周期资源利用与系统可持续性', 'L', '目标2'),
(8, 1, 1, '8-2', '8. 职业规范', '具有软件工程师职业道德与软件知识产权保护规范', 'H', '目标1'),
(9, 1, 1, '9-2', '9. 个人和团队', '能够在多角色人机协同开发团队中承担轮值DRI与质量审查职责', 'H', '目标2'),
(10, 1, 1, '10-1', '10. 沟通', '能够撰写符合IEEE标准的工程规范与Sprint评审报告', 'M', '目标1'),
(11, 1, 1, '11-1', '11. 项目管理', '全面掌握软件经济决策、MoSCoW需求分级与工期缓冲池机制', 'H', '目标1'),
(12, 1, 1, '12-2', '12. 终身学习', '具有跟踪并吸收现代智能化软件工程新技术的敏锐度', 'M', '目标2');
